 async function changePcquotePart(index,category,part){const base=plans[index];const parts={...base.parts,[category]:part};let result;try{const r=await fetch('/api/quotes/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requirement:req,settings,parts:Object.fromEntries(Object.entries(parts).map(([c,p])=>[c,p.id]))}),signal:AbortSignal.timeout(30000)});result=await r.json();if(!r.ok)throw new Error(result.error||'재계산 실패');}catch(e){setToast(`부품 교체를 계산하지 못했습니다: ${e.message}`);return;}const issues=result.checks.filter(c=>c.ok!==true);if(issues.length)setToast(`호환성 경고: ${issues.map(c=>`${c.label} — ${c.detail}`).join(' · ')}`);else if(!usablePart(part))setToast('데이터 확인 경고: 선택한 부품의 가격 또는 성능 정보가 확인되지 않았습니다.');if(result.warnings?.length)parts.board={...parts.board,biosPreparation:`출고 전 확인: ${result.warnings.join(' · ')}`};else if(parts.board.biosPreparation?.startsWith('출고 전 확인:')){const {biosPreparation,...board}=parts.board;parts.board=board;}setPlans(old=>old.map((p,i)=>i===index?{...p,parts,total:total(parts,settings),checks:result.checks,performance:result.performance,popularity:result.popularity,upgrades:undefined}:p));}
 async function confirmQuote(){setIssuedAt(new Date().toISOString());const p=plans[selected];if(!p)return;const cap=limitFor(p,req);if(p.checks.some(x=>!x.ok)||Object.values(p.parts).some(x=>!usablePart(x))||p.total>cap||(!demo&&p.catalogVersion&&p.catalogVersion!==dataset?.catalogVersion)){setToast('발행 전 확인: '+quoteBlocks.join(' · '));return}const entry={catalogVersion:dataset?.catalogVersion,id:crypto.randomUUID(),date:new Date().toISOString(),plan:p,req,settings:{...settings},customerName:(customerNameInput.current?.value??customerName).trim(),name:planNames[selected]};if(!api){setToast('DB 서버에 연결할 수 없어 견적을 저장하지 못했습니다. 서버 연결을 확인해 주세요.');return}try{const r=await fetch('/api/quotes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(entry)});const saved=await r.json();if(!r.ok)throw new Error(saved.error);Object.assign(entry,saved);}catch(e){setToast('서버 저장 실패: '+e.message);return;}setHistory(h=>[entry,...h].slice(0,100));setModal('quote');}
